import fs from 'node:fs';
import path from 'node:path';
import { gzipSync } from 'node:zlib';
import { config } from '../config';
import type { Chunk, DocumentRecord } from '../types';
import { chunkDocument } from './chunker';
import { embedTexts, dimensions } from '../retrieval/embeddings';
import { replaceChunks, exportIndex } from '../retrieval/store';
export function documents(): DocumentRecord[] {
  return JSON.parse(fs.readFileSync(path.resolve('fixtures/documents/manifest.json'), 'utf8'));
}
export function readDocument(doc: DocumentRecord) {
  const root = path.resolve('fixtures/documents');
  const filename = path.resolve(root, doc.file);
  if (!filename.startsWith(root + path.sep)) throw new Error('Invalid document path.');
  let text = fs.readFileSync(filename, 'utf8');
  if (filename.endsWith('.html'))
    text = text
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ')
      .replace(/&amp;/g, '&');
  return text.replace(/\r\n/g, '\n');
}
export async function ingest(onProgress: (value: string) => void = () => {}) {
  const docs = documents();
  const chunks: Chunk[] = docs.flatMap((doc) => chunkDocument(doc, readDocument(doc)));
  onProgress(`${docs.length} documents · ${chunks.length} chunks`);
  const vectors = await embedTexts(chunks.map((c) => c.text));
  const complete = chunks.map((c, i) => ({ ...c, vector: vectors[i] }));
  replaceChunks(complete, { model: config.embeddingModel, dimensions });
  onProgress('Index updated.');
  return {
    documents: docs.length,
    chunks: complete.length,
    model: config.embeddingModel,
    dimensions,
  };
}
export function saveInitialIndex() {
  fs.mkdirSync('fixtures/embeddings', { recursive: true });
  fs.writeFileSync('fixtures/embeddings/index.json.gz', gzipSync(JSON.stringify(exportIndex())));
}
import { createHash } from 'node:crypto';
import type { Chunk, DocumentRecord } from '../types';
export function chunkDocument(doc: DocumentRecord, text: string): Chunk[] {
  const chunks: Chunk[] = [];
  for (let offset = 0; offset < text.length; offset += 650) {
    const part = text.slice(offset, offset + 650).trim();
    if (!part) continue;
    chunks.push({
      id: createHash('sha256').update(`${doc.id}:${offset}:${part}`).digest('hex').slice(0, 24),
      documentId: doc.id,
      text: part,
      title: offset === 0 ? doc.title : null,
      version: offset === 0 ? doc.version : null,
      validFrom: offset === 0 ? doc.validFrom : null,
      validTo: offset === 0 ? doc.validTo : null,
      audience: doc.audience,
    });
  }
  return chunks;
}
import { appDb } from '../db';
import { config } from '../config';
import { embedTexts } from './embeddings';
import { allChunks } from './store';
import type { SearchResult } from '../types';
export async function searchDocuments(
  query: string,
  role = 'customer',
  limit = 5,
): Promise<SearchResult[]> {
  const meta = appDb().prepare('SELECT value FROM meta WHERE key=?').get('index-model') as
    { value: string } | undefined;
  if (!meta) throw new Error('No document index. Run npm run setup or npm run ingest.');
  if (meta.value !== config.embeddingModel)
    throw new Error('The model does not match the index. Re-ingest the documents.');
  const [queryVector] = await embedTexts([query]);
  return allChunks()
    .filter((c) => role === 'operator' || c.audience === 'public')
    .map(({ vector, ...c }) => {
      if (vector!.length !== queryVector.length) throw new Error('Incompatible embedding dimensions.');
      const score = vector!.reduce((sum, v, i) => sum + v * queryVector[i], 0);
      return { ...c, score };
    })
    .sort((a, b) => b.score - a.score)
    .slice(0, limit);
}
import { appDb } from '../db';
import { config } from '../config';
import { vectorBuffer, readVector, embeddingKey } from './embeddings';
import type { Chunk } from '../types';
export type IndexDump = {
  format: 1;
  model: string;
  dimensions: number;
  chunks: (Omit<Chunk, 'vector'> & { vectorBase64: string })[];
};
export function replaceChunks(chunks: Chunk[], settings: { model: string; dimensions: number }) {
  const db = appDb();
  db.transaction(() => {
    db.exec('DELETE FROM chunks');
    const insert = db.prepare('INSERT INTO chunks VALUES(?,?,?,?,?,?,?,?,?)');
    for (const c of chunks) {
      if (c.vector?.length !== settings.dimensions) throw new Error('Incomplete index.');
      insert.run(
        c.id,
        c.documentId,
        c.text,
        c.title,
        c.version,
        c.validFrom,
        c.validTo,
        c.audience,
        vectorBuffer(c.vector),
      );
    }
    db.prepare('INSERT OR REPLACE INTO meta VALUES(?,?)').run('index-model', settings.model);
    db.prepare('INSERT OR REPLACE INTO meta VALUES(?,?)').run(
      'index-dimensions',
      String(settings.dimensions),
    );
  })();
}
export function allChunks(): Chunk[] {
  return (appDb().prepare('SELECT * FROM chunks ORDER BY id').all() as any[]).map((r) => ({
    id: r.id,
    documentId: r.document_id,
    text: r.text,
    title: r.title,
    version: r.version,
    validFrom: r.valid_from,
    validTo: r.valid_to,
    audience: r.audience,
    vector: readVector(r.vector),
  }));
}
export function exportIndex(): IndexDump {
  const db = appDb();
  const model = (
    db.prepare('SELECT value FROM meta WHERE key=?').get('index-model') as { value: string }
  ).value;
  const dimensions = Number(
    (db.prepare('SELECT value FROM meta WHERE key=?').get('index-dimensions') as { value: string })
      .value,
  );
  return {
    format: 1,
    model,
    dimensions,
    chunks: allChunks().map(({ vector, ...c }) => ({
      ...c,
      vectorBase64: vectorBuffer(vector!).toString('base64'),
    })),
  };
}
export function restoreIndex(index: IndexDump) {
  if (index.format !== 1 || index.model !== config.embeddingModel)
    throw new Error('The initial index uses a different model. Run npm run ingest.');
  const chunks = index.chunks.map(({ vectorBase64, ...c }) => ({
    ...c,
    vector: readVector(Buffer.from(vectorBase64, 'base64')),
  }));
  replaceChunks(chunks, { model: index.model, dimensions: index.dimensions });
  const db = appDb();
  db.transaction(() => {
    for (const c of chunks)
      db.prepare('INSERT OR REPLACE INTO embedding_cache VALUES(?,?)').run(
        embeddingKey(c.text),
        vectorBuffer(c.vector),
      );
  })();
}
import OpenAI from 'openai';
import { createHash } from 'node:crypto';
import { appDb } from '../db';
import { config } from '../config';
export const dimensions = 1536;
export function vectorBuffer(vector: number[]) {
  return Buffer.from(new Float32Array(vector).buffer);
}
export function readVector(buffer: Buffer) {
  return Array.from(
    new Float32Array(buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength)),
  );
}
export function embeddingKey(text: string) {
  return createHash('sha256')
    .update(`${config.embeddingModel}:${dimensions}:text-v1:${text}`)
    .digest('hex');
}
export class MissingOpenAIKeyError extends Error {
  constructor() {
    super(
      'Set OPENAI_API_KEY in .env.local or the environment to use the agent and semantic search, then restart the services.',
    );
    this.name = 'MissingOpenAIKeyError';
  }
}
export function openai() {
  if (!process.env.OPENAI_API_KEY?.trim()) throw new MissingOpenAIKeyError();
  return new OpenAI({ apiKey: process.env.OPENAI_API_KEY, maxRetries: 2, timeout: 45000 });
}
export async function embedTexts(texts: string[]): Promise<number[][]> {
  const db = appDb(),
    result: number[][] = new Array(texts.length),
    missing: { index: number; text: string; key: string }[] = [];
  texts.forEach((text, index) => {
    const key = embeddingKey(text),
      cached = db.prepare('SELECT vector FROM embedding_cache WHERE key=?').get(key) as
        { vector: Buffer } | undefined;
    if (cached) result[index] = readVector(cached.vector);
    else missing.push({ index, text, key });
  });
  for (let offset = 0; offset < missing.length; offset += 48) {
    const batch = missing.slice(offset, offset + 48);
    const response = await openai().embeddings.create({
      model: config.embeddingModel,
      input: batch.map((x) => x.text),
      dimensions,
      encoding_format: 'float',
    });
    for (const item of response.data) {
      const target = batch[item.index];
      if (!target || item.embedding.length !== dimensions)
        throw new Error('Unexpected dimensions returned by the embeddings API.');
      result[target.index] = item.embedding;
      db.prepare('INSERT OR REPLACE INTO embedding_cache VALUES(?,?)').run(
        target.key,
        vectorBuffer(item.embedding),
      );
    }
    if (batch.some((x) => !result[x.index])) throw new Error('Incomplete embeddings response.');
  }
  return result;
}
