  const dimensions = Number(
    (db.prepare('SELECT value FROM meta WHERE key=?').get('index-dimensions') as { value: string })
      .value,
  );
  return {
    format: 1,
    model,
    dimensions,
    chunks: allChunks().map(({ vector, ...c }) => ({
      ...c,
      vectorBase64: vectorBuffer(vector!).toString('base64'),
