      return;
    }
    if (url.pathname.startsWith('/v1/operations/') && req.method === 'GET') {
      const op = operationByReference(
        actor,
        decodeURIComponent(url.pathname.slice('/v1/operations/'.length)),
      );
      if (!op) throw new HttpError(404, 'Operation not found.');
      reply(200, op);
      return;
    }
